    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xD670D4C50DA4E94FULL + 0xBBE6960DD3E86E48ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0x8EA69E80C34ED87FULL + 0xC8218CBFBDA68CE2ULL);
