            //
            aOrbiterK = ((aWandererK + RotL64(aCross, 28U)) + 0xBD57D888ECC8B8F5ULL) + aTwistOrbiterAssignSaltE[((aIndex + 25U)) & S_SALT1];
            aOrbiterE = ((aWandererF + RotL64(aScatter, 21U)) + RotL64(aCarry, 5U)) + 0x9CB1CB6D3881BE21ULL;
            aOrbiterC = (aWandererA + RotL64(aPrevious, 5U)) + 0x6C99A9C15F0932F8ULL;
            aOrbiterH = (aWandererD + RotL64(aIngress, 13U)) + 0xB05439F614EB2C52ULL;
            aOrbiterA = ((aWandererG + RotL64(aCross, 47U)) + RotL64(aCarry, 43U)) + 0xD5AB022D9E808614ULL;
            aOrbiterI = ((aWandererJ + RotL64(aPrevious, 37U)) + RotL64(aCarry, 23U)) + 0x4B59F28CD85A528DULL;
            aOrbiterG = ((aWandererH + RotL64(aIngress, 57U)) + 0x9F7218952A47266AULL) + aTwistOrbiterAssignSaltF[((aIndex + 28U)) & S_SALT1];
            //
            aOrbiterK = ((aOrbiterK + aOrbiterE) + 0x0A92AE371DAA7A52ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 21U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0x7F1AC9AA336EBE7AULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x09DA26E6B90C7413ULL), 43U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0xA6C1BF2787E5CBC5ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x32F68DD6954536B4ULL;
