            aOrbiterK = (aWandererB + RotL64(aPrevious, 57U)) + 0x2A90D4D8CF77DB50ULL;
            aOrbiterH = (aWandererI + RotL64(aIngress, 43U)) + 0xED7123460EF0EA2EULL;
