            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0xB781A24199947D55ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xE9D5FA15209D59F6ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xD7C377B6F120F189ULL), 51U);
