            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0x7B169B2BA6D5E5D3ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x603014BD2A39ECFCULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 29U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x1B4A1522694EA8BBULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xD86C6BD6F6FC1DB9ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x3A5AE67BB9191792ULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 13U)) & S_SALT1];
