            aWandererH = aWandererH ^ ((RotL64(aScatter, 56U) + RotL64(aOrbiterF, 27U)) + aOrbiterH);
            aWandererB = aWandererB + ((((RotL64(aCross, 39U) + RotL64(aOrbiterG, 37U)) + aOrbiterD) + RotL64(aCarry, 27U)) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 43U) + RotL64(aOrbiterH, 19U)) + aOrbiterC);
