            aOrbiterI = (aOrbiterI + aOrbiterA) + 0xF155829E5AF34414ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xD34A179962D3DD3EULL;
            aOrbiterK = RotL64((aOrbiterK * 0x7EC3D054B7EC83D3ULL), 57U);
