            aWandererH = aWandererH + (((RotL64(aIngress, 53U) + aOrbiterG) + RotL64(aOrbiterD, 24U)) + aKeyRotateAWandererUpdateSaltD[(((31U - aIndex) + 29U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 57U) + aOrbiterC) + RotL64(aOrbiterI, 13U));
            aWandererI = aWandererI + ((RotL64(aPrevious, 3U) + aOrbiterD) + RotL64(aOrbiterF, 47U));
            aWandererC = aWandererC ^ ((RotL64(aCross, 44U) + RotL64(aOrbiterK, 39U)) + aOrbiterJ);
            aWandererB = aWandererB + ((RotL64(aPrevious, 19U) + aOrbiterK) + RotL64(aOrbiterB, 28U));
