            aIngress ^= (RotL64(aSoilLaneC[((aIndex + 4319U)) & S_BLOCK1], 43U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 7451U)) & S_BLOCK1], 27U));
