            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x8F89E12937198C63ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xB28E32663B589872ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x493C3C9C7C42F293ULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x47B25125A888B795ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0x3C99278361C04063ULL;
