            aWandererG = aWandererG + ((RotL64(aPrevious, 51U) + RotL64(aOrbiterB, 51U)) + aOrbiterI);
            aWandererA = aWandererA ^ (((RotL64(aScatter, 13U) + RotL64(aOrbiterK, 10U)) + aOrbiterD) + aKeyRotateAWandererUpdateSaltE[((aIndex + 11U)) & S_SALT1]);
