            aWandererE = aWandererE ^ ((RotL64(aIngress, 37U) + RotL64(aOrbiterA, 21U)) + aOrbiterE);
            aWandererB = aWandererB + (((RotL64(aScatter, 11U) + aOrbiterH) + RotL64(aOrbiterB, 13U)) + RotL64(aCarry, 19U));
            aWandererK = aWandererK ^ ((RotL64(aCross, 47U) + aOrbiterG) + RotL64(aOrbiterF, 27U));
            aWandererJ = aWandererJ + ((RotL64(aIngress, 27U) + aOrbiterC) + RotL64(aOrbiterB, 34U));
            aWandererD = aWandererD ^ ((RotL64(aScatter, 6U) + aOrbiterK) + RotL64(aOrbiterA, 39U));
            aWandererH = aWandererH + (((RotL64(aPrevious, 21U) + aOrbiterC) + RotL64(aOrbiterJ, 37U)) + RotL64(aCarry, 13U));
