            //
            aOrbiterE = ((aWandererE + RotL64(aIngress, 51U)) + 0x048EA28D5094A2DAULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterC = (aWandererH + RotL64(aScatter, 29U)) + 0x2FD4F79E392BDF41ULL;
            aOrbiterH = ((aWandererF + RotL64(aPrevious, 5U)) + RotL64(aCarry, 43U)) + 0x17CB11358BB5F4F8ULL;
            aOrbiterJ = (((aWandererC + RotL64(aCross, 35U)) + RotL64(aCarry, 19U)) + 0x1E42D47DA2D3D436ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 7U)) & S_SALT1];
            aOrbiterB = (aWandererK + RotL64(aPrevious, 23U)) + 0xC2A9D77B0315624BULL;
