            aCross ^= (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 11451U)) & S_BLOCK1], 41U) ^ RotL64(aPoisonLaneB[((aIndex + 12277U)) & S_BLOCK1], 13U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 56U) + RotL64(aCross, 5U)) ^ (RotL64(aIngress, 35U) + RotL64(aCarry, 21U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 19U)) + 0xA3F50A06468BD179ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 22U)) & S_SALT1];
            aOrbiterB = ((aWandererC + RotL64(aScatter, 5U)) + RotL64(aCarry, 29U)) + 0x976FE4472384326DULL;
            aOrbiterH = (aWandererD + RotL64(aIngress, 11U)) + 0x4F51D1D0EE381945ULL;
            aOrbiterI = (aWandererJ + RotL64(aCross, 36U)) + 0x0A173BF091084263ULL;
            aOrbiterC = (aWandererB + RotL64(aIngress, 53U)) + 0x9C5A2745B862980DULL;
            aOrbiterK = ((aWandererF + RotL64(aPrevious, 43U)) + RotL64(aCarry, 43U)) + 0xB67811D11C0453BEULL;
            aOrbiterJ = (((aWandererG + RotL64(aCross, 29U)) + RotL64(aCarry, 13U)) + 0x8D5EEA837B3BE630ULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 20U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x9ABAB625B422A0EEULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x815F2BB036EF8C5CULL;
            aOrbiterH = RotL64((aOrbiterH * 0xAB8FE91513DCACCDULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0xE503495BADE94252ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0xE9A7D342CD99A6DBULL;
            aOrbiterC = RotL64((aOrbiterC * 0x1D4618344C4BFBBBULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x641286AFE2D754CFULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0xFA837D9C30D8E8A1ULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 17U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x3417EE08CE5DDABFULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x64268D0C18E65DDDULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterJ) ^ 0x2D7A38439E53D1B7ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x3D36CA235C969BDDULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x27DD4E6FA1D35DE7ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x225339391CE22E66ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x44BD51AF30BCC0DBULL), 47U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0xE5A96F203B242573ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0x61F5E5A4A13E1DF0ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xB6855913D3962F45ULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xA7B235324D71E5A7ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x896A5413BD741659ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xFDEF5B0A19B710A9ULL), 35U);
            //
            aIngress = RotL64(aOrbiterD, 35U) ^ aOrbiterK;
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterJ, 11U));
