            //
            aWandererC = aWandererC ^ (((RotL64(aScatter, 3U) + RotL64(aOrbiterK, 37U)) + aOrbiterD) + aKeyRotateAWandererUpdateSaltD[((aIndex + 7U)) & S_SALT1]);
            aWandererG = aWandererG + (((RotL64(aCross, 43U) + RotL64(aOrbiterK, 21U)) + aOrbiterH) + RotL64(aCarry, 27U));
            aWandererF = aWandererF ^ ((RotL64(aIngress, 37U) + RotL64(aOrbiterB, 29U)) + aOrbiterD);
            aWandererB = aWandererB + (((RotL64(aPrevious, 52U) + aOrbiterJ) + RotL64(aOrbiterI, 43U)) + RotL64(aCarry, 47U));
            aWandererD = aWandererD ^ (((RotL64(aIngress, 27U) + aOrbiterK) + RotL64(aOrbiterI, 53U)) + aKeyRotateAWandererUpdateSaltB[((aIndex + 24U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aPrevious, 21U) + aOrbiterB) + RotL64(aOrbiterJ, 60U));
            aWandererA = aWandererA ^ ((RotL64(aCross, 11U) + aOrbiterC) + RotL64(aOrbiterH, 11U));
