            aIngress = (RotL64(aFuseLaneB[((aIndex + 17292U)) & S_BLOCK1], 27U) ^ RotL64(aWindLaneD[((aIndex + 17773U)) & S_BLOCK1], 39U));
            aIngress ^= (RotL64(aShadowLaneC[((aIndex + 21760U)) & S_BLOCK1], 13U) ^ RotL64(aPlasmaLaneD[((aIndex + 17969U)) & S_BLOCK1], 60U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 17075U)) & S_BLOCK1], 30U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 18853U)) & S_BLOCK1], 13U));
            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 16782U)) & W_KEY1], 43U) ^ RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 23346U)) & S_BLOCK1], 21U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 41U) + RotL64(aPrevious, 27U)) + (RotL64(aCarry, 53U) ^ RotL64(aIngress, 10U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterD = (aWandererB + RotL64(aIngress, 57U)) + 0xEFD413010B6C1626ULL;
            aOrbiterK = ((aWandererH + RotL64(aCross, 11U)) + RotL64(aCarry, 23U)) + 0x4CAC660CABC3DF21ULL;
            aOrbiterI = ((aWandererI + RotL64(aPrevious, 29U)) + 0xC1719F2E06A95425ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterH = ((aWandererD + RotL64(aScatter, 47U)) + RotL64(aCarry, 47U)) + 0x171354B16A28E831ULL;
            aOrbiterC = (((aWandererF + RotL64(aIngress, 37U)) + RotL64(aCarry, 5U)) + 0xAF77B963C3AFECC6ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 14U)) & S_SALT1];
            aOrbiterE = (aWandererJ + RotL64(aPrevious, 18U)) + 0xF68BCEDFA2642E9CULL;
            aOrbiterB = (aWandererK + RotL64(aScatter, 3U)) + 0x933F2AEB65C88172ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x3DAF4D7B04F0139FULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0x187B4AE70BC69111ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x9C84A21EE0E521B3ULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0xD07A891785579663ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0x115BE1030FE540E2ULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 11U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x9D3E9473D939BABBULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x4E4E4E65B4702BB8ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x7B19B9BE67B2AF4DULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF749E2334363DCB1ULL), 57U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0xC26E36CD82484741ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0x6AE0F5E2E8A958ADULL;
            aOrbiterC = RotL64((aOrbiterC * 0x92732E48369CA8FDULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0xB6EC2559661241DCULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x311AE561A82B3359ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0CD692244382705BULL), 19U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0xD33F4109BBAA1563ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0xF446C39BB5ACB566ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xF3EBBEF43142993BULL), 43U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x551CF1DEEDCA4118ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x97D15CD773CB3B8FULL;
            aOrbiterK = RotL64((aOrbiterK * 0x602CEE3120EABB8DULL), 37U);
            //
            aIngress = aOrbiterD ^ RotL64(aOrbiterH, 3U);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterK, 13U));
            aIngress = aIngress + (RotL64(aOrbiterC, 21U) ^ aOrbiterB);
            aIngress = aIngress + RotL64(aOrbiterE, 41U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererF = aWandererF + (((RotL64(aIngress, 19U) + RotL64(aOrbiterB, 12U)) + aOrbiterC) + RotL64(aCarry, 5U));
            aWandererH = aWandererH ^ ((RotL64(aScatter, 35U) + aOrbiterI) + RotL64(aOrbiterD, 19U));
            aWandererK = aWandererK + (((RotL64(aCross, 53U) + RotL64(aOrbiterH, 29U)) + aOrbiterC) + RotL64(aCarry, 43U));
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 42U) + aOrbiterB) + RotL64(aOrbiterK, 57U));
            aWandererJ = aWandererJ + (((RotL64(aIngress, 3U) + RotL64(aOrbiterI, 5U)) + aOrbiterK) + aKeyRotateAWandererUpdateSaltA[((aIndex + 25U)) & S_SALT1]);
            aWandererB = aWandererB ^ (((RotL64(aPrevious, 11U) + RotL64(aOrbiterE, 37U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltC[((aIndex + 13U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aScatter, 27U) + aOrbiterI) + RotL64(aOrbiterH, 47U));
