            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterK = ((aWandererC + RotL64(aPrevious, 51U)) + RotL64(aCarry, 5U)) + 0xEF3D64C6EAD63327ULL;
            aOrbiterC = (((aWandererG + RotL64(aScatter, 3U)) + RotL64(aCarry, 41U)) + 0xCA1DB3DB18D7C8FDULL) + aKeyRotateBOrbiterAssignSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterB = (((aWandererJ + RotL64(aCross, 60U)) + RotL64(aCarry, 57U)) + 0x2691B8DABDA24362ULL) + aKeyRotateBOrbiterAssignSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterA = (aWandererA + RotL64(aIngress, 23U)) + 0xA1154885817C05FBULL;
            aOrbiterG = (aWandererB + RotL64(aCross, 13U)) + 0xF9FB33161FB75DDEULL;
            aOrbiterF = (aWandererD + RotL64(aIngress, 41U)) + 0xEE57330DB97866B9ULL;
            aOrbiterE = (aWandererE + RotL64(aScatter, 29U)) + 0xF68EB833B0E8DE03ULL;
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0x2838F33961C4A225ULL) + aKeyRotateBOrbiterUpdateSaltE[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x6AF671A99D0B27E1ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x382DBDD022DCB60FULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterG) + 0x39EC97AF7B2CA510ULL;
